function unchangedAfterRotations(grid: number[][], k: number): boolean {
  const g = grid.map(row => row.slice());
  for (let step = 0; step < k; step++) {
    g.forEach((row, i) => {
      if (i % 2 === 0) row.push(row.shift()!);
      else row.unshift(row.pop()!);
    });
  }
  return g.every((row, i) => row.every((v, j) => v === grid[i][j]));
}

