class Solution:
    def unchangedAfterRotations(self, grid: List[List[int]], k: int) -> bool:
        g = [deque(row) for row in grid]
        for _ in range(k):
            for i, row in enumerate(g):
                row.rotate(-1 if i % 2 == 0 else 1)
        return all(list(g[i]) == grid[i] for i in range(len(grid)))

